import sys; sys.path.insert(0, '_tools'); from spec import enrich
enrich('las-facetas-del-yo-soy-vii', 'A',
 [dict(t=746, e=796, titulo='Necesitamos quien nos guíe en el camino', txt='Usted se ha dado cuenta que cuando uno va en un sendero, a veces aparecen caminos que parecen más fáciles, pero hay caminos que parecen buenos y su finalidad es de muerte. Una de las cosas que quiero comentarle, ahora que vamos a hablar del camino: usted y yo no podemos solos en ese camino. Necesitamos quien nos guíe. ¿A usted quién lo guía? A mí, el apóstol Sergio, a través de la unción que desciende sobre él; pero el que nos guía es el Señor Jesucristo. Y eso es bien importante, hermano.'),
  dict(t=947, e=994, titulo='Este camino no es fácil, pero te lleva al Padre', txt='Si nosotros reconocemos el camino a través del Señor Jesucristo por medio del Espíritu Santo, ya la hicimos. Ahora quiero decirle que este camino no es fácil. Diga conmigo: este camino no es fácil, pero te lleva a la salvación; este camino no es fácil, pero te lleva al Padre; este camino no es fácil, pero cambia tu vida; este camino no es fácil, pero yo soy feliz en medio de este camino. Aunque haya problemas, aunque haya situaciones difíciles, yo sé que el Señor me ha tomado de su mano, porque él es el camino y me está llevando hacia el Padre.'),
  dict(t=1200, e=1245, titulo='Yo reconozco que tú eres el camino', txt='Pero ese marcar así, si se da cuenta, el camino se volvió, ¿qué? Estrecho. Por eso no es fácil. Por eso es que hay que rendirse; por eso uno tiene que decirle al Señor: «Aquí estoy y le voy a hacer ganas. No importa lo que pase, yo estoy contigo, Señor. No importa lo que está sucediendo alrededor mío: yo lo único que sé es que tú me salvaste, que ya me mostraste el camino y que tengo que seguir en él. Yo reconozco que tú eres el camino, que tú eres la verdad; y si yo reconozco esa verdad, voy a tener vida».')],
 [dict(t=815, txt='Hemos sido llamados a ser discípulos de esta iglesia: no solo oyentes, no solo creyentes, discípulos.'),
  dict(t=1163, txt='Jesucristo, después de que resucitó, marcó el camino. Antes no; cuando ya resucitó, marcó el camino.'),
  dict(t=1269, txt='Este es un tiempo de liberación. Va a haber mucha liberación desde hoy en adelante.')],
 ['¿Quién te guía en el camino y cómo estás recibiendo esa guía del Espíritu Santo a través de los hombres de Dios?',
  '¿Cuál de las frases «este camino no es fácil, pero…» necesitas declarar hoy sobre tu propia situación?',
  '¿De qué necesitas ser liberado esta semana para seguir en el camino que Jesús marcó?'],
 inicio=553)
